import { useEffect, useState } from 'react'
import type { Candle } from '../data'
import {
  PERP_WS, SPOT_WS, klines, msToNextDayUTC8, perpDepth, perpTicker, premium, spotTickers, stream,
  type Level, type Premium, type Ticker,
} from './binance'

export type FeedState = 'loading' | 'live' | 'offline'

/**
 * Spot tickers for today (from 00:00 UTC+8): REST trading-day snapshot, then
 * live prices from <sym>@miniTicker measured against that day's open. The
 * snapshot is re-fetched at each UTC+8 midnight so the change restarts at 0.
 */
export function useSpotTickers(symbols: string[]) {
  const [tickers, setTickers] = useState<Record<string, Ticker>>({})
  const [state, setState] = useState<FeedState>('loading')
  const key = symbols.join(',')
  useEffect(() => {
    let alive = true
    let timer: ReturnType<typeof setTimeout> | undefined
    const load = () => {
      spotTickers(symbols).then(t => { if (alive) { setTickers(t); setState('live') } }).catch(() => alive && setState('offline'))
      timer = setTimeout(load, msToNextDayUTC8() + 2000) // a moment after midnight, when Binance has opened the new day
    }
    load()
    const close = stream(SPOT_WS, symbols.map(s => `${s.toLowerCase()}@miniTicker`), (_s, d) => {
      const price = +d.c
      setTickers(prev => {
        const day = prev[d.s]
        if (!day) return prev // wait for today's open from the snapshot
        return { ...prev, [d.s]: { ...day, price, chg: day.open ? ((price - day.open) / day.open) * 100 : 0,
          high: Math.max(day.high, price), low: Math.min(day.low, price) } }
      })
    })
    return () => { alive = false; clearTimeout(timer); close() }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key])
  return { tickers, state }
}

/** 7-day trend lines (28 × 6h closes) per symbol, fetched once. */
export function useTrends(symbols: string[]) {
  const [trends, setTrends] = useState<Record<string, number[]>>({})
  const key = symbols.join(',')
  useEffect(() => {
    let alive = true
    Promise.allSettled(symbols.map(s => klines(s, '6h', 28))).then(rs => {
      if (!alive) return
      const out: Record<string, number[]> = {}
      rs.forEach((r, i) => { if (r.status === 'fulfilled') out[symbols[i]] = r.value.map(c => c.c) })
      setTrends(out)
    })
    return () => { alive = false }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key])
  return trends
}

export type PerpFeed = {
  state: FeedState
  ticker?: Ticker
  premium?: Premium
  bids: Level[]
  asks: Level[]
  candles: Candle[]
}

/** USDT-M perpetual: ticker, mark/funding, top-20 depth and klines, all streamed. */
export function usePerp(symbol: string, interval: string): PerpFeed {
  const [feed, setFeed] = useState<PerpFeed>({ state: 'loading', bids: [], asks: [], candles: [] })
  useEffect(() => {
    let alive = true
    const s = symbol.toLowerCase()
    setFeed(f => ({ ...f, candles: [] }))
    Promise.all([perpTicker(symbol), premium(symbol), perpDepth(symbol), klines(symbol, interval, 60, true)])
      .then(([ticker, prem, depth, cs]) => alive && setFeed({ state: 'live', ticker, premium: prem, ...depth, candles: cs }))
      .catch(() => alive && setFeed(f => ({ ...f, state: 'offline' })))
    const close = stream(PERP_WS, [`${s}@ticker`, `${s}@markPrice@1s`, `${s}@depth20@100ms`, `${s}@kline_${interval}`], (name, d) => {
      setFeed(f => {
        if (name.endsWith('@ticker')) {
          return { ...f, ticker: { sym: d.s, price: +d.c, open: +d.o, chg: +d.P, high: +d.h, low: +d.l, quoteVol: +d.q } }
        }
        if (name.includes('@markPrice')) {
          return { ...f, premium: { mark: +d.p, index: +d.i, funding: +d.r, nextFunding: d.T } }
        }
        if (name.includes('@depth')) {
          const lv = (a: [string, string][]): Level[] => a.map(([p, q]) => [+p, +q])
          return { ...f, bids: lv(d.b), asks: lv(d.a) }
        }
        if (name.includes('@kline') && f.candles.length) {
          const k = d.k, c: Candle = { t: k.t, o: +k.o, h: +k.h, l: +k.l, c: +k.c, v: +k.v }
          const last = f.candles[f.candles.length - 1]
          const candles = last.t === c.t ? [...f.candles.slice(0, -1), c] : [...f.candles.slice(1), c]
          return { ...f, candles }
        }
        return f
      })
    }, live => alive && live && setFeed(f => (f.state === 'offline' ? { ...f, state: 'live' } : f)))
    return () => { alive = false; close() }
  }, [symbol, interval])
  return feed
}

/** Re-render every second (for countdowns). */
export function useNow(ms = 1000) {
  const [now, setNow] = useState(Date.now())
  useEffect(() => { const id = setInterval(() => setNow(Date.now()), ms); return () => clearInterval(id) }, [ms])
  return now
}
